class Solution {
public:
    bool validPath(int n, vector<vector<int>>& edges, int source, int destination) {
        vector<int> parent(n), rank(n, 0);
        iota(parent.begin(), parent.end(), 0);
        auto find = [&](auto& self, int i) -> int {
            if (parent[i] != i) parent[i] = self(self, parent[i]);
            return parent[i];
        };
        auto unite = [&](int i, int j) {
            int rootI = find(find, i), rootJ = find(find, j);
            if (rootI != rootJ) {
                if (rank[rootI] < rank[rootJ]) parent[rootI] = rootJ;
                else if (rank[rootI] > rank[rootJ]) parent[rootJ] = rootI;
                else {
                    parent[rootJ] = rootI;
                    rank[rootI]++;
                }
            }
        };
        for (auto& e : edges) unite(e[0], e[1]);
        return find(find, source) == find(find, destination);
    }
};

class Solution {
    public boolean validPath(int n, int[][] edges, int source, int destination) {
        int[] parent = new int[n];
        int[] rank = new int[n];
        for (int i = 0; i < n; i++) parent[i] = i;
        for (int[] e : edges) union(e[0], e[1], parent, rank);
        return find(source, parent) == find(destination, parent);
    }
    private int find(int i, int[] parent) {
        if (parent[i] != i) parent[i] = find(parent[i], parent);
        return parent[i];
    }
    private void union(int i, int j, int[] parent, int[] rank) {
        int rootI = find(i, parent), rootJ = find(j, parent);
        if (rootI != rootJ) {
            if (rank[rootI] < rank[rootJ]) parent[rootI] = rootJ;
            else if (rank[rootI] > rank[rootJ]) parent[rootJ] = rootI;
            else {
                parent[rootJ] = rootI;
                rank[rootI]++;
            }
        }
    }
}

var validPath = function(n, edges, source, destination) {
    const parent = Array.from({ length: n }, (_, i) => i);
    const rank = new Array(n).fill(0);
    function find(i) {
        if (parent[i] !== i) parent[i] = find(parent[i]);
        return parent[i];
    }
    function union(i, j) {
        const rootI = find(i), rootJ = find(j);
        if (rootI !== rootJ) {
            if (rank[rootI] < rank[rootJ]) parent[rootI] = rootJ;
            else if (rank[rootI] > rank[rootJ]) parent[rootJ] = rootI;
            else {
                parent[rootJ] = rootI;
                rank[rootI]++;
            }
        }
    }
    for (const [u, v] of edges) union(u, v);
    return find(source) === find(destination);
};
